using MediatR;using Namaa.Application.Abstractions.Authentication;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Common.Errors;using Namaa.Application.PaymentVouchers.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PaymentVouchers.Commands.PostPaymentVoucher;public sealed class PostPaymentVoucherCommandHandler(IPaymentVoucherRepository repository,IUserRepository users,ICurrentUser currentUser,IApplicationDbContext db):IRequestHandler<PostPaymentVoucherCommand,Result<PaymentVoucherDto>>{public async Task<Result<PaymentVoucherDto>>Handle(PostPaymentVoucherCommand request,CancellationToken cancellationToken){if(!currentUser.IsAuthenticated||currentUser.UserId is not long actorUserId)return Result.Failure<PaymentVoucherDto>(ApplicationErrors.Unauthenticated);var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.NotDraft);if(!await users.ExistsByIdAsync(actorUserId,cancellationToken))return Result.Failure<PaymentVoucherDto>(new Error("PaymentVouchers.UserNotFound","The user was not found.",ErrorType.NotFound));e.Post(actorUserId,request.PostedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentVoucherDto.FromEntity(e));}}
